    content = r['research_content']
    major_raw = classification_major(info.get('classification'))
    major_family_name = info.get('major_family')
    if not isinstance(major_family_name, str) or not major_family_name:
        major_family_name, _ignored, _error = major_admission(major_raw)
        major_family_name = major_family_name or (major_raw or '未识别')
    p = r['artifact_profile']
    return {'artifact_domain':'education','artifact_domain_version':'1.0.2','artifact_domain_config_sha256':'efe1359f3c31a8c293980f64fad5d6ac6682ad3e940301abde6dba6bea89037e','artifact_profile_version':'1.0', 'artifact_profile':packed(p),
        'artifact_paper_type':p['paper_type'], 'artifact_research_path':p['research_path'],
